"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["680300"],{97772(a){a.exports=JSON.parse('{"tag":{"label":"sys_ui_macro","permalink":"/sdk/4.14.0/tags/sys-ui-macro","allTagsPath":"/sdk/4.14.0/tags","count":4,"items":[{"id":"api/service-catalog/variables/customvariable-api","title":"CustomVariable","description":"A CatalogItem variable for a custom UI component field. Custom variables embed a UI Macro, Service Portal Widget, Macroponent, or Virtual Agent Topic Block directly into a catalog form \u2014 replacing the standard input control with a fully custom rendering.","permalink":"/sdk/4.14.0/api/service-catalog/variables/customvariable-api"},{"id":"api/service-catalog/variables/customwithlabelvariable-api","title":"CustomWithLabelVariable","description":"A CatalogItem variable for a custom UI component field with a displayed label. Like CustomVariable, it embeds a UI Macro, Service Portal Widget, Macroponent, or Virtual Agent Topic Block into a catalog form \u2014 but it also renders the question text as a visible label above the custom component.","permalink":"/sdk/4.14.0/api/service-catalog/variables/customwithlabelvariable-api"},{"id":"guides/ui-macro-guide","title":"UI Macros","description":"Guide for creating ServiceNow UI Macros (sysuimacro) with the Fluent UiMacro API. UI Macros are reusable Jelly components that render HTML and can run server-side script; in Fluent they are used to back custom form formatters (via a sysuiformatter Record() and a Form() formatter element referencing it) and to power custom Service Catalog variable types via CustomVariable and CustomWithLabelVariable.","permalink":"/sdk/4.14.0/guides/ui-macro-guide"},{"id":"api/uimacro-api","title":"UiMacro","description":"Creates a UI Macro \u2014 a reusable Jelly component that accepts parameters, renders HTML, and can run server-side script (sysuimacro). UI Macros are invoked by name from Jelly UI Pages, form formatters, Service Catalog variable types, and other UI Macros.","permalink":"/sdk/4.14.0/api/uimacro-api"}],"unlisted":false}}')}}]);